package finance.bank;
import java.util.UUID;
public final class InterbankLoan {private final UUID id,lender,borrower;private final long principal,issueDay,maturityDay;private final int rateBps;private InterbankLoanStatus status;public InterbankLoan(UUID id,UUID lender,UUID borrower,long principal,int rateBps,long issueDay,long maturityDay,InterbankLoanStatus status){if(id==null||lender==null||borrower==null||lender.equals(borrower)||principal<=0||rateBps<0||rateBps>100_000||issueDay<0||maturityDay<=issueDay||status==null)throw new IllegalArgumentException();this.id=id;this.lender=lender;this.borrower=borrower;this.principal=principal;this.rateBps=rateBps;this.issueDay=issueDay;this.maturityDay=maturityDay;this.status=status;}public UUID id(){return id;}public UUID lenderBankId(){return lender;}public UUID borrowerBankId(){return borrower;}public long principal(){return principal;}public int rateBasisPoints(){return rateBps;}public long issueDay(){return issueDay;}public long maturityDay(){return maturityDay;}public InterbankLoanStatus status(){return status;}void setStatus(InterbankLoanStatus s){status=s;}}
